    /** Sum of a VSOP87 series (in 1e-8 units), returned in radians / AU. */
    fun sumSeries(series: Array<DoubleArray>, tau: Double): Double {
        var sum = 0.0
        var power = 1.0
        for (terms in series) {
            var s = 0.0
            var i = 0
            while (i < terms.size) {
                s += terms[i] * Math.cos(terms[i + 1] + terms[i + 2] * tau)
                i += 3
            }
            sum += s * power
            power *= tau
        }
        return sum / 1e8
    }
